{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 기부채납 공원 준공인가 신청 시 점검 대상에 흙(토양) 포함 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 도시공원 조례 제31조제1항에 따르면, 공원관리청은 기부채납 대상 공원 및 녹지에 대해 준공인가 신청 시 점검하여야 하며, 그 점검 사항에는 ‘토양 등 식재기반 조성에 대한 점검’이 포함되어 있습니다. 따라서 시설과 나무(식재)뿐 아니라 흙(토양)도 점검 대상에 포함됩니다.",
          "b_ids": "도시공원:제31조제1항, 도시공원:제31조제1항제2호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
